121		private void removeKeeper(String clusterId, String shardId, KeeperMeta keeperMeta) {
122			try {
123				keeperStateController.removeKeeper(new KeeperTransMeta(clusterId, shardId, keeperMeta));
124			} catch (Exception e) {
125				logger.error(String.format("[removeKeeper]%s:%s,%s", clusterId, shardId, keeperMeta), e);
126			}
