84			
85			if(!currentMetaManager.hasCluster(clusterId)){
86				logger.info("[changePrimaryDc][not interested in this cluster]");
87				return new PrimaryDcChangeMessage(PRIMARY_DC_CHANGE_RESULT.SUCCESS, "not interested in this cluster:" + clusterId);
88			}
89			
90			ChangePrimaryDcAction changePrimaryDcAction = null;
91	
92			ExecutionLog executionLog = new ExecutionLog(String.format("meta server:%s", currentClusterServer.getClusterInfo()));
93			if(newPrimaryDc.equalsIgnoreCase(dcMetaCache.getCurrentDc())){
94				logger.info("[doChangePrimaryDc][become primary]{}, {}, {}", clusterId, shardId, newPrimaryDc);
95				changePrimaryDcAction = new BecomePrimaryAction(dcMetaCache, currentMetaManager, sentinelManager,
96						offsetWaiter, executionLog, keyedObjectPool, createNewMasterChooser(), scheduled, executors);
97				ChangePrimaryDcJob changePrimaryDcJob = createChangePrimaryDcJob(changePrimaryDcAction, clusterId, shardId,
98						newPrimaryDc, masterInfo);
