100				try {
101					clusterShardExecutors.clearAndExecute(new Pair<>(clusterId, shardId), changePrimaryDcJob);
102					waitForCommandStart(changePrimaryDcJob);
103					return changePrimaryDcJob.future().get(timeout, TimeUnit.MILLISECONDS);
104				} catch (TimeoutException|InterruptedException e) {
105					logger.error("[changePrimaryDc][execute may timeout][fall to run directly]{}, {}, {}", clusterId, shardId, newPrimaryDc, e);
106					// In case task queue is blocked, we do downgrade(or a double-insurance)
107					try {
108						return createChangePrimaryDcJob(changePrimaryDcAction, clusterId, shardId, newPrimaryDc, masterInfo)
109								.execute().get();
110					} catch (Exception innerException) {
111						logger.error("[changePrimaryDc][try direct-run failed]{}, {}, {}", clusterId, shardId, newPrimaryDc, e);
112						return new PrimaryDcChangeMessage(PRIMARY_DC_CHANGE_RESULT.FAIL, executionLog.getLog());
113					}
